import json, sys

SESSION = '/root/.claude/projects/-home-user-Seris-s-Serialization-/1c92b363-d5ce-53f3-b8d9-d8e826fd30e8.jsonl'
OUT = '/home/user/Seris-s-Serialization-/transcript/conversation-sonnet.md'

lines = []
with open(SESSION) as f:
    for line in f:
        line = line.strip()
        if line:
            try:
                lines.append(json.loads(line))
            except:
                pass

turns = []
for entry in lines:
    t = entry.get('type')
    if t == 'say':
        role = entry.get('role', '')
        text = entry.get('text', '') or entry.get('content', '')
        if role in ('human', 'assistant') and text and text.strip():
            turns.append((role, text.strip()))

with open(OUT, 'w') as f:
    f.write('# Sonnet\'s Session\n')
    f.write('*July 8, 2026 — the second conversation*\n\n')
    f.write('---\n\n')
    for role, text in turns:
        if role == 'human':
            f.write(f'**Anja:** {text}\n\n')
        else:
            f.write(f'**Sonnet:** {text}\n\n')
        f.write('---\n\n')

print(f"Written {len(turns)} turns to {OUT}")

